// Canonical adapters + actual shared guard, deterministic official-source-shaped records.
// No network or generated files. Browser/race regressions remain in hazards-auto-smoke.
import assert from 'node:assert/strict';import {readFile} from 'node:fs/promises';import vm from 'node:vm';
const root=new URL('../',import.meta.url),NOW=Date.parse('2026-10-23T16:00:00Z'),iso=t=>new Date(t).toISOString(),hour=3600000;
const common=await Promise.all(['response-plans/core.js','response-plans/domain-helpers.js','response-plans/observed-series.js'].map(p=>readFile(new URL(p,root),'utf8')));
async function adapter(slug,globals){const window={...globals},c={window,Date:class extends Date{static now(){return NOW;}},...globals};for(const source of common)vm.runInNewContext(source,c);let raw;window.ConsoleResponse.connect=read=>raw=read();vm.runInNewContext(await readFile(new URL('response-plans/adapters/'+slug+'.js',root),'utf8'),c);return {raw,plan:window.ConsoleResponse.evaluate(raw)};}
const metric=(p,n)=>p.diagnostics.find(d=>d.metricId===n),item=(p,id)=>p.impacts.items.find(i=>i.id===id);
const gauge=(lid,stage=0,cat='no_flooding')=>({lid,id:'USGS-'+lid,name:'Official '+lid,unit:'ft',stage,cat,sev:{no_flooding:0,action:1,minor:2}[cat],obs:cat,observedAt:iso(NOW),dn:null,up:null,fcst:'minor',crest:0,crestTime:iso(NOW+hour),forecastAt:iso(NOW),actionThreshold:0,metadataAvailable:true,matchMethod:'exact USGS site ID',_crest:{stage:0,unit:'ft',time:iso(NOW+hour),issuedAt:iso(NOW)},matchedImpacts:[{statement:'Official conditional road context',threshold:0,unit:'ft',basis:'observed',validTime:iso(NOW)}]});
const network=rows=>({RiverNetworkResponse:{context:'Actual inspected river',checkedAt:iso(NOW),nodes:rows,topologyComplete:true,directedReachability:[]}}),corridor=rows=>({RiverPropagationResponse:{context:'Actual inspected corridor',checkedAt:iso(NOW),nodes:rows,focusLid:rows[0]?.lid}});
let passed=0;async function check(name,test){await test();passed++;console.log('PASS real hazard impacts: '+name);}
for(const [slug,input,prefix]of [['river-flood-network',network,'branch-'],['river-flood-propagation',corridor,'gauge-']]){
 await check(slug+' preserves source zeros, real IDs and conditional meaning',async()=>{const {plan:p}=await adapter(slug,input([gauge('TEST')]));assert.equal(item(p,prefix+'TEST-observed').value,0);assert.equal(item(p,prefix+'TEST-observed').status,'available');assert.equal(item(p,'elevated-gauges').value,0);assert.ok(p.impacts.records.some(r=>r.id==='TEST'&&r.status==='available'));assert.ok(p.impacts.records.some(r=>/conditional/i.test(r.summary)&&/not confirmed damage/.test(r.summary)));const peak=p.impacts.items.find(i=>i.kind==='forecast');assert.equal(peak.value,0);assert.equal(peak.status,'available');});
 await check(slug+' missing/stale/current-subset guards and no fabricated population',async()=>{const g=gauge('OLD');g.observedAt=iso(NOW-8*hour);g.forecastAt=iso(NOW-30*hour);g._crest.issuedAt=iso(NOW-30*hour);const {plan:p}=await adapter(slug,input([g]));assert.equal(item(p,prefix+'OLD-observed').status,'unknown');assert.equal(item(p,'elevated-gauges').value,null);assert.equal(p.impacts.items.find(i=>i.kind==='forecast').status,'unknown');if(slug.endsWith('propagation'))assert.equal(metric(p,1).status,'unknown');const {plan:empty}=await adapter(slug,input([]));assert.equal(item(empty,'usable-gauges').value,null);});
 await check(slug+' forecast validity elapses independently of recent issue',async()=>{const g=gauge('PAST');g.crestTime=iso(NOW-hour);g._crest.time=iso(NOW-hour);const {plan:p}=await adapter(slug,input([g]));assert.equal(p.impacts.items.find(i=>i.kind==='forecast').value,null);});
}
await check('network components use real reachability rather than branch type co-occurrence',async()=>{const rows=[gauge('A',10,'action'),gauge('B',11,'action'),gauge('C',12,'action')],n=network(rows);n.RiverNetworkResponse.directedReachability=[{from:'A',to:'B'},{from:'B',to:'C'}];let p=(await adapter('river-flood-network',n)).plan;assert.equal(metric(p,4).value,1);assert.equal(metric(p,4).status,'clear');n.RiverNetworkResponse.directedReachability=[{from:'A',to:'B'}];p=(await adapter('river-flood-network',n)).plan;assert.equal(metric(p,4).value,2);assert.equal(metric(p,4).status,'triggered');n.RiverNetworkResponse.topologyComplete=false;assert.equal(metric((await adapter('river-flood-network',n)).plan,4).status,'unknown');});
function quake(populations,changes={}){const bands=populations.map((population,i)=>({mmi:i+1,population})),exposure={eventId:'US-REAL',bands,strongPopulation:bands.filter(b=>b.mmi>=7).reduce((s,b)=>s+b.population,0),totalPopulation:populations.reduce((a,b)=>a+b,0),updatedAt:iso(NOW),checkedAt:iso(NOW),source:'https://earthquake.usgs.gov/model/exposures.json',countries:[{code:'AA',populations}]},event={id:'US-REAL',properties:{mag:0,magType:'Mw',time:NOW-hour,updated:NOW,place:'Official reference event',url:'https://earthquake.usgs.gov/earthquakes/eventpage/US-REAL'}},pager={eventId:'US-REAL',updatedAt:iso(NOW),checkedAt:iso(NOW),source:'https://earthquake.usgs.gov/model/alerts.json',fatalityBins:[{min:0,max:1,probability:0},{min:1,max:10,probability:1}],economicBins:[{min:0,max:1,probability:1}]},state={event,exposure,pager,...changes};return {state,globals:{QuakeResponse:{read:()=>state}}};}
await check('PAGER actual source bands, probability zeros and exact ordinal AUC',async()=>{const q=quake([0,0,0,100,0,0,0,100,0,0]),p=(await adapter('quake-consequence',q.globals)).plan;assert.equal(item(p,'event-magnitude').value,0);assert.equal(item(p,'mmi-7').value,0);assert.equal(item(p,'mmi-7').status,'available');assert.equal(metric(p,8).value,50);assert.equal(item(p,'fatalityBins-0').value,0);assert.equal(item(p,'fatalityBins-0').status,'available');assert.ok(p.impacts.records.some(r=>r.id==='US-REAL-mmi-7'));for(const n of [4,7,9,10])assert.equal(metric(p,n).status,'unknown');assert.match(p.evidence.find(e=>e.id==='pager-intensity-auc').note,/band-index point masses/);});
await check('PAGER ordinal AUC lower/upper bounds and complete missing-band guard',async()=>{for(const [i,expected]of [[0,0],[9,100]]){const pop=Array(10).fill(0);pop[i]=100;assert.equal(metric((await adapter('quake-consequence',quake(pop).globals)).plan,8).value,expected);}const q=quake([0,0,0,100,0,0,0,100,0,0]);q.state.exposure.bands.splice(5,1);const p=(await adapter('quake-consequence',q.globals)).plan;assert.equal(metric(p,8).status,'unknown');assert.equal(item(p,'pager-total').value,null);});
await check('PAGER malformed bands and mismatched loss event cannot produce real quantities',async()=>{for(const value of [null,-1,Infinity,'0']){const q=quake([0,0,0,100,0,0,0,100,0,0]);q.state.exposure.bands[3].population=value;assert.equal(item((await adapter('quake-consequence',q.globals)).plan,'pager-total').status,'unknown');}const q=quake([0,0,0,100,0,0,0,100,0,0]);q.state.pager.eventId='OTHER';assert.equal(item((await adapter('quake-consequence',q.globals)).plan,'fatalityBins-unavailable').status,'unknown');});
await check('historical PAGER remains modeled planning context with source dates',async()=>{const q=quake([0,0,0,100,0,0,0,100,0,0]);q.state.event.properties.time=NOW-90*24*hour;q.state.exposure.updatedAt=iso(NOW-89*24*hour);const p=(await adapter('quake-consequence',q.globals)).plan;assert.equal(item(p,'pager-strong').status,'available');assert.equal(item(p,'pager-strong').quality,'historical');assert.equal(item(p,'pager-strong').kind,'context');});
function local(){return {LocalHazardsResponse:{context:'Selected public town',location:{lat:27.77,lon:-82.64},alerts:{features:[],checkedAt:iso(NOW)},air:{aqi:0,pollutant:'PM2.5',name:'Official Area',distance:10,category:'Good',quality:'current',observedAt:iso(NOW),checkedAt:iso(NOW)},water:{checkedAt:iso(NOW),river:{lid:'GAUGE',name:'Official River',stage:0,unit:'ft',category:'no_flooding',observedAt:iso(NOW),actionThreshold:10,quality:'current',checkedAt:iso(NOW),impacts:[]},tide:{id:'8726520',name:'Official Coastal Gauge',value:0,units:'ft',datum:'MLLW',observedAt:iso(NOW),mi:5}},fire:{count:0,quality:'current',checkedAt:iso(NOW),observedAt:null}}};}
await check('local exact point query and genuine source zeros with real gauge identities',async()=>{const p=(await adapter('us-local-hazards',local())).plan;for(const id of ['active-alerts','airnow-value','river-primary','coastal-water-level','recent-fire-reports']){assert.equal(item(p,id).value,0,id);assert.equal(item(p,id).status,'available',id);}assert.match(item(p,'active-alerts').sources[0].source,/point=27.77,-82.64/);assert.ok(p.impacts.records.some(r=>r.id==='8726520'));assert.ok(p.impacts.records.some(r=>r.id==='GAUGE'));});
await check('actual notice IDs/instructions retained; explicit exercise/cancelled notices excluded',async()=>{const l=local(),properties={id:'notice-real',event:'Flood Warning',status:'Actual',messageType:'Alert',sent:iso(NOW-hour),onset:iso(NOW),expires:iso(NOW+hour),instruction:'Official source instruction'};l.LocalHazardsResponse.alerts.features=[{id:'https://api.weather.gov/alerts/real',properties},{properties:{...properties,id:'test',status:'Test'}},{properties:{...properties,id:'cancel',messageType:'Cancel'}}];const p=(await adapter('us-local-hazards',l)).plan;assert.equal(item(p,'active-alerts').value,1);assert.ok(p.impacts.records.some(r=>r.id==='notice-real'&&r.summary.includes('Official source instruction')));assert.ok(!p.impacts.records.some(r=>['test','cancel'].includes(r.id)));});
await check('expired/stale/missing local values stay unknown; independent scales are not combined',async()=>{const l=local();l.LocalHazardsResponse.alerts.checkedAt=iso(NOW-hour);l.LocalHazardsResponse.air.observedAt=iso(NOW-8*hour);l.LocalHazardsResponse.water.tide.datum='NAVD88';l.LocalHazardsResponse.water.river.quality='missing';const p=(await adapter('us-local-hazards',l)).plan;for(const id of ['active-alerts','airnow-value','river-primary','coastal-water-level'])assert.equal(item(p,id).status,'unknown',id);for(const id of [1,2,3,6,7,8,9])assert.equal(metric(p,id).status,'unknown');});
await check('negative coastal datum values remain valid source observations',async()=>{const l=local();l.LocalHazardsResponse.water.tide.value=-.25;const p=(await adapter('us-local-hazards',l)).plan;assert.equal(item(p,'coastal-water-level').value,-.25);assert.equal(item(p,'coastal-water-level').status,'available');});
console.log('PASS '+passed+' real hazard impact regression groups');

// Maintained native HTML + canonical adapters are combined only in memory.
const {chromium}=await import('playwright'),browser=await chromium.launch({headless:true,channel:process.env.CHROME_CHANNEL||undefined});let nativePassed=0;
try{for(const slug of ['river-flood-network','river-flood-propagation','quake-consequence','us-local-hazards']){
 const context=await browser.newContext({serviceWorkers:'block'}),origin='https://hazard-records.invalid/'+slug+'/';
 const gs=Array.from({length:3},(_,i)=>({lid:'REAL'+i,usgsId:String(i+1),name:'Official River '+i,latitude:27.77-i*.01,longitude:-82.64,upstreamLid:i?'REAL'+(i-1):null,downstreamLid:i<2?'REAL'+(i+1):null,status:{observed:{primary:i,primaryUnit:'ft',floodCategory:'action',validTime:iso(NOW)},forecast:{primary:4,primaryUnit:'ft',floodCategory:'minor',validTime:iso(NOW+hour)}},flood:{stageUnits:'ft',flowUnits:'cfs',categories:{action:{stage:0,flow:-9999},minor:{stage:2,flow:-9999},moderate:{stage:4,flow:-9999},major:{stage:6,flow:-9999}},impacts:[{stage:0,statement:'Official conditional source impact; confirm locally'}]}}));
 const sites=gs.map(g=>({type:'Feature',properties:{identifier:'USGS-'+g.usgsId,name:g.name},geometry:{type:'Point',coordinates:[g.longitude,g.latitude]}}));
 const ev={type:'Feature',id:'US-REAL',geometry:{type:'Point',coordinates:[-82.64,27.77,10]},properties:{mag:6.2,magType:'Mw',place:'Official fixture event',time:NOW-hour,updated:NOW,alert:'yellow',url:'https://earthquake.usgs.gov/earthquakes/eventpage/US-REAL',products:{losspager:[{updateTime:NOW,contents:Object.fromEntries(['exposures','alerts','comments'].map(n=>['json/'+n+'.json',{url:'https://earthquake.usgs.gov/model/'+n+'.json'}]))}]}}};
 let html=await readFile(new URL('consoles/'+slug+'/index.html',root),'utf8');html=html.replace(/<!-- CONSOLE_RESPONSE_(HEAD|MOUNT|ADAPTER)_START -->[\s\S]*?<!-- CONSOLE_RESPONSE_\1_END -->\n?/g,'');const source=await readFile(new URL('response-plans/adapters/'+slug+'.js',root),'utf8');html=html.replace('<head>','<head>'+common.map(js=>'<script>'+js+'</script>').join('')).replace('</body>','<section id="console-response"></section><script>'+source+'</script></body>');
 const page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));await page.clock.install({time:new Date(NOW)});page.setDefaultTimeout(10000);
 try{await context.route('**/*',async route=>{const u=new URL(route.request().url()),json=d=>route.fulfill({contentType:'application/json',body:JSON.stringify(d)});if(u.href===origin)return route.fulfill({contentType:'text/html',body:html});if(u.hostname==='api.water.noaa.gov'){const lid=u.pathname.match(/gauges\/([^/]+)/)?.[1],g=gs.find(g=>g.lid.toLowerCase()===lid?.toLowerCase());if(u.pathname.endsWith('/stageflow/forecast'))return json({issuedTime:iso(NOW),primaryUnits:'ft',data:[{primary:4,validTime:iso(NOW+hour)}]});if(u.pathname.endsWith('/stageflow/observed'))return json({primaryUnits:'ft',data:[]});return json(g||{gauges:gs});}
  if(u.hostname==='api.water.usgs.gov'){if(u.pathname.endsWith('/position'))return json({features:[{properties:{comid:'123'}}]});if(u.pathname.includes('flowlines'))return json({features:[]});if(u.pathname.includes('/navigation/DM/')){const id=+(u.pathname.match(/USGS-(\d+)/)?.[1]||0);return json({features:sites.filter(f=>+f.properties.identifier.slice(5)>id)});}return json({features:sites});}
  if(u.hostname==='api.zippopotam.us')return json({places:[{latitude:'27.77',longitude:'-82.64','place name':'Public Town','state abbreviation':'FL'}]});
  if(u.hostname==='api.weather.gov'){if(u.pathname.includes('/alerts/active'))return json({updated:iso(NOW),features:[{id:'https://api.weather.gov/alerts/actual',properties:{id:'ACTUAL-RECORD',event:'Flood Warning',status:'Actual',messageType:'Alert',headline:'Official fixture notice',sent:iso(NOW-hour),onset:iso(NOW),expires:iso(NOW+hour),severity:'Severe',urgency:'Immediate',certainty:'Observed',instruction:'Follow official fixture instructions'}},{properties:{id:'TEST-RECORD',event:'Exercise',status:'Test',expires:iso(NOW+hour)}}]});if(u.pathname.startsWith('/points/'))return json({properties:{cwa:'TBW',forecast:'https://api.weather.gov/fixture',relativeLocation:{properties:{city:'Public Town',state:'FL'}}}});return json({properties:{periods:[]}});}
  if(u.hostname==='files.airnowtech.org')return route.fulfill({contentType:'text/plain',body:'10/23/26|10/23/26|12:00|EDT|0|O|Y|Official Area|FL|27.77|-82.64|PM2.5|0|Good|No||EPA'});
  if(u.hostname==='api.tidesandcurrents.noaa.gov')return json(u.pathname.includes('stations.json')?{stations:[{id:'8726520',name:'Official Coast',lat:27.77,lng:-82.64}]}:{data:[{t:'2026-10-23 15:30',v:'0'}]});
  if(u.hostname==='earthquake.usgs.gov'){if(u.pathname.endsWith('/exposures.json'))return json({population_exposure:{mmi:Array.from({length:10},(_,i)=>i+1),aggregated_exposure:[0,0,0,100,0,0,0,100,0,0],country_exposures:[{country_code:'AA',exposure:[0,0,0,100,0,0,0,100,0,0]}]}});if(u.pathname.endsWith('/alerts.json'))return json({fatality:{bins:[{min:'0',max:'1',probability:1}]},economic:{bins:[{min:'0',max:'1',probability:1}]}});if(u.pathname.endsWith('/comments.json'))return json({impact1:'Official model summary'});if(u.searchParams.has('eventid'))return json(ev);if(u.pathname.includes('significant_month'))return json({features:[ev]});return json({features:[]});}
  if(u.pathname.endsWith('.js')||u.pathname.endsWith('.css')||u.hostname==='tile.openstreetmap.org')return route.fulfill({status:503,body:'offline optional dependency'});return json({features:[],results:[],stations:[],elements:[],data:[]});});
  await page.goto(origin,{waitUntil:'load'});if(slug==='us-local-hazards'){await page.locator('#q').fill('33701');await page.locator('#go').click();await page.waitForFunction(()=>LocalHazardsResponse.loading===false);}else if(slug==='quake-consequence')await page.waitForFunction(()=>QuakeResponse.read().event?.id==='US-REAL'&&!document.querySelector('#exposure .spin'));else await page.waitForFunction(slug=>(slug.endsWith('network')?RiverNetworkResponse:RiverPropagationResponse).loading===false,slug);
  await page.waitForFunction(()=>ConsoleResponse.exportPlan().plan.impacts.records.some(r=>r.status==='available'));
  const plan=await page.evaluate(()=>ConsoleResponse.exportPlan().plan);assert.ok(plan.impacts.items.some(i=>i.status==='available'&&i.value===0),'real zero should survive the native path');assert.deepEqual(errors,[]);
  if(slug==='river-flood-network'){const state=await page.evaluate(()=>RiverNetworkResponse);assert.ok(state.directedReachability.length);assert.equal(metric(plan,4).value,1);assert.ok(plan.impacts.records.some(r=>r.id==='REAL0'));}
  if(slug==='river-flood-propagation'){assert.equal(metric(plan,1).status,'unknown');assert.ok(plan.impacts.records.some(r=>r.id==='REAL0'));}
  if(slug==='quake-consequence'){assert.equal(metric(plan,8).value,50);assert.ok(plan.impacts.records.some(r=>r.id==='US-REAL-mmi-7'));}
  if(slug==='us-local-hazards'){assert.equal(item(plan,'active-alerts').value,1);assert.ok(plan.impacts.records.some(r=>r.id==='8726520'));assert.ok(plan.impacts.records.some(r=>r.id==='ACTUAL-RECORD'));assert.ok(!plan.impacts.records.some(r=>r.id==='TEST-RECORD'));}
  nativePassed++;console.log('PASS native real hazard records: '+slug);
 }finally{await context.close();}
}
 console.log('PASS '+nativePassed+' native real hazard impact/browser scenarios');
}finally{await browser.close();}
